/**
 * The app, in Italian.
 *
 * Keyed on the ENGLISH source string, exactly as the other tables are, because
 * that is what ui() is handed at the call site. One character out and the
 * lookup misses in silence: the app draws the English and nothing anywhere
 * reports a problem.
 *
 * ADDRESS. Tu throughout, never Lei — an app talking to one person who chose
 * to be here, not a form. That matches the German table's du, the Portuguese
 * table's tu, and the plain second person of the English source.
 *
 * AND THE COURSE IS STILL GERMAN. This table is what the app says about
 * itself; the cards keep saying German whatever is chosen here. So "the
 * German word" stays "la parola tedesca" and is not quietly generalised —
 * a learner reading the app in Italian is still learning German unless they
 * picked otherwise.
 */
