  "Make a set for whatever keeps slipping — irregular verbs, words from a conversation, anything. You can pull cards from the catalogue instead of typing them.": "Crea un gruppo per quello che continua a sfuggirti: verbi irregolari, parole di una conversazione, qualsiasi cosa. Puoi prendere le carte dal catalogo invece di scriverle.",
