  "Empty. Drag a set here, or use \"Move to folder\" on any card.": "Vuota. Trascina qui un gruppo, oppure usa “Sposta in una cartella” su una carta qualsiasi.",
  "Not in a folder": "Fuori da ogni cartella",
  "Tip: in the editor, \"From catalogue\" searches every word and phrase the app already knows — genders, glosses and usage notes come with them, so you rarely have to type a card yourself.": "Consiglio: nell'editor, “Dal catalogo” cerca fra tutte le parole e le frasi che l'app già conosce: generi, glosse e note d'uso arrivano insieme, così raramente devi scrivere una carta a mano.",
