  "Add a card": "Aggiungi una carta",
  "Paste a list": "Incolla un elenco",
  "One card per line. Separate the two sides with a tab, a dash, an equals sign or a colon — a tab is what you get pasting two columns out of a spreadsheet.": "Una carta per riga. Separa i due lati con una tabulazione, un trattino, un segno di uguale o due punti: la tabulazione è quello che ottieni incollando due colonne da un foglio di calcolo.",
  "Preview": "Anteprima",
  "no second side": "nessun secondo lato",
  "more": "altre",
  "Send this set to someone": "Manda questo gruppo a qualcuno",
  "Copy the text below and paste it into a message. Whoever receives it pastes it back in here — it is the same format the paste box already reads.": "Copia il testo qui sotto e incollalo in un messaggio. Chi lo riceve lo incolla di nuovo qui: è lo stesso formato che il riquadro di incollaggio già legge.",
  "Receive a set": "Ricevi un gruppo",
  "Paste a shared set here to add its cards to this one. The title and description stay as they are.": "Incolla qui un gruppo condiviso per aggiungere le sue carte a questo. Il titolo e la descrizione restano come sono.",
  "from": "da",
  "Stages": "Fasi",
  "A Learn session walks each card up this ladder. Reorder or switch off whichever you like; what it takes to climb is set below.": "Una sessione di studio fa salire ogni carta lungo questa scala. Riordina o disattiva quello che vuoi; quanto serve per salire si imposta qui sotto.",
  "Remove stage": "Rimuovi la fase",
  "Add a stage": "Aggiungi una fase",
  "How the ladder is climbed": "Come si sale la scala",
  "Right answers to promote": "Risposte giuste per salire",
  "How many in a row before a card moves up a stage. One is quick; four makes you prove it.": "Quante di fila prima che una carta salga di una fase. Una è veloce; quattro te lo fanno dimostrare.",
  "Cards per round": "Carte per turno",
  "How many a Learn session asks before it stops and shows you where you got to.": "Quante ne chiede una sessione di studio prima di fermarsi e mostrarti a che punto sei.",
  "A mistake costs a stage": "Un errore costa una fase",
  "On: getting one wrong drops the card back down the ladder. Off: it only resets the streak, so a slip never undoes work.": "Attivo: sbagliarne una fa scendere la carta lungo la scala. Disattivo: azzera solo la serie, così una svista non disfa mai il lavoro.",
  "Which side is asked": "Quale lato viene chiesto",
