  "Credits and licences": "Crediti e licenze",
  "Micheon is written by Leon and Michelle. These are the pieces it stands on, and the licences they are used under.": "Micheon è scritto da Leon e Michelle. Questi sono i pezzi su cui si regge, e le licenze con cui sono usati.",
