  "{name} removed. Opening the course downloads it again.": "{name} rimossa. Aprire il corso la riscarica.",
  "Could not remove {name}.": "Non è stato possibile rimuovere {name}.",
  "Import replaces this profile's saved data. Shared preferences and custom words also apply to this computer's local app. Other profiles are untouched. Continue?": "L'importazione sostituisce i dati salvati di questo profilo. Le preferenze condivise e le parole personali valgono anche per l'app locale di questo computer. Gli altri profili restano intatti. Continuare?",
  "Downloaded languages": "Lingue scaricate",
  "A language downloads itself when you open its course. Remove one to get the space back — opening the course again brings it straight back.": "Una lingua si scarica da sola quando apri il suo corso. Rimuovine una per recuperare lo spazio: riaprire il corso la riporta subito indietro.",
  "Space on this computer": "Spazio su questo computer",
  "Recheck": "Ricontrolla",
  "Micheon and the course": "Micheon e il corso",
  "The program itself. Cannot be removed from in here.": "Il programma stesso. Da qui non si può rimuovere.",
  "Your saved data": "I tuoi dati salvati",
  "Progress, settings, and your own words.": "Progressi, impostazioni e le tue parole.",
  "Cache": "Cache",
  "Temporary files. Safe to clear.": "File temporanei. Si possono svuotare senza problemi.",
  "Clearing…": "Svuoto…",
  "Clear cache": "Svuota la cache",
  "Disk figures are only available in the desktop app.": "I dati sul disco sono disponibili solo nell'app desktop.",
  "About languages: the German course is built into the program rather than installed separately, so there is nothing to uninstall that would save you space. The other languages are not here yet, and take up nothing.": "Sulle lingue: il corso di tedesco è dentro il programma invece di essere installato a parte, quindi non c'è niente da disinstallare che ti faccia guadagnare spazio. Le altre lingue non sono ancora qui e non occupano niente.",
  "Move your Micheon data": "Sposta i tuoi dati di Micheon",
  "Take your progress, settings, custom words, mastery and installed pets to another computer with a private JSON file.": "Porta progressi, impostazioni, parole personali, padronanza e mascotte installate su un altro computer con un file JSON privato.",
  "Exporting…": "Esporto…",
