  "Import data": "Importa i dati",
  "Import replaces this profile's saved data. Shared preferences and custom words also apply to this computer's local app. Other profiles are untouched.": "L'importazione sostituisce i dati salvati di questo profilo. Le preferenze condivise e le parole personali valgono anche per l'app locale di questo computer. Gli altri profili restano intatti.",
  "What Micheon is storing for you": "Che cosa Micheon conserva per te",
