  "Everything above, for this account on this device. Your account stays, and other profiles on this computer are untouched. This cannot be undone.": "Tutto quello qui sopra, per questo account su questo dispositivo. Il tuo account resta, e gli altri profili di questo computer restano intatti. L'operazione non si può annullare.",
