  "Move with ← → and shoot with Space. Hit the right form of the verb. Wrong answer = game over.": "Muoviti con ← → e spara con la barra spaziatrice. Colpisci la forma giusta del verbo. Risposta sbagliata = partita finita.",
  "Wrong!": "Sbagliato!",
