  "Read the {meaning} prompt, then steer into its {target} translation. Every correct answer gives you a new phrase. Avoid the wrong choices and enemy snakes.": "Leggi la richiesta in {meaning}, poi punta sulla sua traduzione in {target}. Ogni risposta giusta ti dà una frase nuova. Evita le scelte sbagliate e i serpenti nemici.",
  "Master the German articles! Guide your snake to consume words that match your target. Watch out for world boundaries and enemy bots!": "Padroneggia gli articoli tedeschi! Guida il tuo serpente a divorare le parole che corrispondono al tuo bersaglio. Attento ai bordi del mondo e ai bot nemici!",
