  "How to play": "Come si gioca",
  "Move your mouse to steer. Hold click or Space to boost. Read the {meaning} prompt and collect its {target} translation. Wrong choices cost points; enemy snakes end the run.": "Muovi il mouse per sterzare. Tieni premuto il clic o la barra spaziatrice per scattare. Leggi la richiesta in {meaning} e raccogli la sua traduzione in {target}. Le scelte sbagliate costano punti; i serpenti nemici chiudono la partita.",
  "Move your mouse to steer. Hold click or Space to boost speed (costs score). Eat words matching the Target Article to grow. Avoid hitting Bots! If a bot hits your body, you get bonus points.": "Muovi il mouse per sterzare. Tieni premuto il clic o la barra spaziatrice per accelerare (costa punti). Mangia le parole che corrispondono all'articolo bersaglio per crescere. Evita di sbattere contro i bot! Se un bot colpisce il tuo corpo, prendi punti bonus.",
  "{language} clue": "indizio in {language}",
