  "Practise the short, natural forms people use. Full forms stay visible and count as correct.": "Esercitati sulle forme brevi e naturali che si usano. Le forme complete restano visibili e contano come giuste.",
  "Practise complete standard forms for formal writing, careful listening, and test answers.": "Esercitati sulle forme standard complete per la scrittura formale, l'ascolto attento e le risposte d'esame.",
  "Low": "Basso",
  "Normal": "Normale",
  "High": "Alto",
  "Use": "Usa",
