  "Mute pet voice": "Silenzia la voce della mascotte",
  "Drag this header to detach and place it anywhere.": "Trascina questa intestazione per staccarla e metterla dove vuoi.",
  "You can change answers to earlier questions.": "Puoi cambiare le risposte alle domande precedenti.",
  "No pet messages yet": "Ancora nessun messaggio della mascotte",
  "Tips and questions will appear here after the mascot speaks.": "I consigli e le domande compariranno qui dopo che la mascotte avrà parlato.",
  "Yes": "Sì",
  "No": "No",
  "Let's practise some German.": "Esercitiamoci un po' con il tedesco.",
  "Los geht's! Let's go.": "Los geht's! Andiamo.",
  "German tip: when a word uses der, die, or das, learn them together — say “der Tisch”, not just “Tisch”.": "Consiglio di tedesco: quando una parola prende der, die o das, imparali insieme: di' “der Tisch”, non solo “Tisch”.",
  "German tip: in a normal German sentence, the verb comes second — “Heute gehe ich nach Hause.”": "Consiglio di tedesco: in una frase tedesca normale il verbo viene per secondo: “Heute gehe ich nach Hause.”",
  "German tip: after weil or dass, put the verb at the end — “weil ich müde bin”.": "Consiglio di tedesco: dopo weil o dass metti il verbo alla fine: “weil ich müde bin”.",
  "German tip: German words for people, places, things, or ideas always start with a capital letter.": "Consiglio di tedesco: in tedesco le parole per persone, luoghi, cose o idee cominciano sempre con la maiuscola.",
  "German tip: some verbs split in two — “aufstehen” becomes “Ich stehe um sieben auf.”": "Consiglio di tedesco: certi verbi si spezzano in due: “aufstehen” diventa “Ich stehe um sieben auf.”",
  "English tip: normal sentences usually put who or what first, then the action, then the rest — “I read the book.”": "Consiglio di inglese: le frasi normali di solito mettono prima chi o che cosa, poi l'azione, poi il resto: “I read the book.”",
  "English tip: after can, must, should, or will, use the verb without “to” — “can go”, not “can to go”.": "Consiglio di inglese: dopo can, must, should o will usa il verbo senza “to”: “can go”, non “can to go”.",
  "English tip: for habits or facts, verbs with he, she, or it usually end in -s — “she works”, “he knows”.": "Consiglio di inglese: per abitudini o fatti, i verbi con he, she o it di solito finiscono in -s: “she works”, “he knows”.",
  "English tip: describing words normally come before the thing — “a red car”. They stay the same — “a nice man”, “a nice woman”.": "Consiglio di inglese: le parole che descrivono di solito vengono prima della cosa: “a red car”. E restano uguali: “a nice man”, “a nice woman”.",
  "English tip: choose “a” or “an” by sound, not spelling — “a university”, but “an hour”.": "Consiglio di inglese: scegli “a” o “an” in base al suono, non alla grafia: “a university”, ma “an hour”.",
  "English tip: after “didn't”, use go, see, or do — not went, saw, or did: “I didn't go.”": "Consiglio di inglese: dopo “didn't” usa go, see o do, non went, saw o did: “I didn't go.”",
  "English tip: “cannot” is one word. Its short form is “can't”.": "Consiglio di inglese: “cannot” è una parola sola. La sua forma breve è “can't”.",
  "English tip: “will not” becomes “won't”, never “willn't”.": "Consiglio di inglese: “will not” diventa “won't”, mai “willn't”.",
  "English tip: German “es gibt” becomes “there is” for one thing and “there are” for several — never “it gives”.": "Consiglio di inglese: il tedesco “es gibt” diventa “there is” per una cosa sola e “there are” per più cose, mai “it gives”.",
  "English tip: when talking about the past, use “there was” for one thing and “there were” for several.": "Consiglio di inglese: quando parli del passato usa “there was” per una cosa sola e “there were” per più cose.",
  "English tip: do not use two negatives together — “I didn't see anything”, not “I didn't see nothing”.": "Consiglio di inglese: non usare due negazioni insieme: “I didn't see anything”, non “I didn't see nothing”.",
  "English tip: “should not” becomes “shouldn't”. The same shortening gives “wouldn't”, “couldn't”, and “mustn't”.": "Consiglio di inglese: “should not” diventa “shouldn't”. La stessa contrazione dà “wouldn't”, “couldn't” e “mustn't”.",
  "English tip: use “haven't” with I, you, we, or they, and “hasn't” with he, she, or it — “I haven't seen it yet”.": "Consiglio di inglese: usa “haven't” con I, you, we o they, e “hasn't” con he, she o it: “I haven't seen it yet”.",
