  "Learn every Windows numpad code for German letters, then practise the characters in real words and sentences. Includes laptop and no-numpad options.": "Impara tutti i codici del tastierino di Windows per le lettere tedesche, poi esercitati sui caratteri in parole e frasi vere. Comprese le opzioni per i portatili e per chi non ha il tastierino.",
  "Num Lock on; hold the left Alt key, enter all four digits on the numeric keypad, then release Alt. The number row above the letters will not work. No numpad? Use Micheon's character buttons, or add US-International or UK Extended in Windows.": "Bloc Num acceso; tieni premuto il tasto Alt sinistro, digita tutte e quattro le cifre sul tastierino numerico, poi rilascia Alt. La fila di numeri sopra le lettere non funziona. Niente tastierino? Usa i pulsanti dei caratteri di Micheon, oppure aggiungi US-International o UK Extended in Windows.",
