  "React naturally, express moods, and fill pauses like a native.": "Reagisci con naturalezza, esprimi gli stati d'animo e riempi le pause come un madrelingua.",
  "The one-liners Germans actually shoot back in conversation. Where a phrase is a clip of a fuller sentence, the note shows the full form — so you learn the word order too.": "Le battute che i tedeschi si rimandano davvero in conversazione. Dove un'espressione è il ritaglio di una frase più lunga, la nota mostra la forma completa, così impari anche l'ordine delle parole.",
  "React fast and naturally, the way people really talk.": "Reagisci in fretta e con naturalezza, come parla davvero la gente.",
