  "Nothing brings it back today": "Oggi niente la riporta",
  "Held back until then": "Trattenuta fino ad allora",
  "Nothing will show this before then.": "Niente te la mostra prima di allora.",
  "Both languages read aloud while you do something else.": "Tutte e due le lingue lette ad alta voce mentre fai altro.",
  "Right now: {words} words + {sentences} sentences = {total} cards at a time, each heard {passes}×. The first {total} play {passes} times over, then the next {total} do the same.": "Adesso: {words} parole + {sentences} frasi = {total} carte alla volta, ognuna ascoltata {passes}×. Le prime {total} passano {passes} volte, poi le {total} successive fanno lo stesso.",
  "Right now: {total} cards at a time, each heard {passes}×. The first {total} play {passes} times over, then the next {total} do the same.": "Adesso: {total} carte alla volta, ognuna ascoltata {passes}×. Le prime {total} passano {passes} volte, poi le {total} successive fanno lo stesso.",
  "Words and sentences": "Parole e frasi",
  "Words only": "Solo parole",
  "Sentences and phrases only": "Solo frasi ed espressioni",
  "Straight away": "Subito",
  "After a few hours": "Dopo qualche ora",
  "After a day": "Dopo un giorno",
  "When the review says so": "Quando lo dice il ripasso",
  "No wait at all. Anything can play again the moment the order reaches it — which on a narrow filter can mean the same handful of cards all evening. Right for a first pass through a new pack, and not much else.": "Nessuna attesa. Qualsiasi cosa può ripartire appena l'ordine ci arriva, il che con un filtro stretto può voler dire la stessa manciata di carte per tutta la sera. Va bene per un primo giro in un pacchetto nuovo, e per poco altro.",
  "About four hours. Long enough that you have to remember it rather than recognise it from a minute ago, and short enough to meet it again the same day.": "Circa quattro ore. Abbastanza da doverla ricordare invece di riconoscerla da un minuto fa, e abbastanza poco da rincontrarla lo stesso giorno.",
  "A full day. This is the shortest gap the review ladder ever asks for, and the point at which hearing something again is recall rather than an echo.": "Un giorno intero. È l'intervallo più corto che la scala dei ripassi chieda mai, e il punto in cui risentire una cosa è richiamo e non eco.",
  "Nothing you have answered correctly comes back until the review ladder says it is due — one day, then three, ten, thirty, a hundred and eighty. Anything you have heard but never answered waits a day.": "Niente a cui hai risposto giusto torna finché la scala dei ripassi non dice che è ora: un giorno, poi tre, dieci, trenta, centottanta. Tutto quello che hai sentito ma a cui non hai mai risposto aspetta un giorno.",
