  "The pictures beside the words. Around eight hundred of them ship with the app, so they look the same on every machine and work with no connection.": "Le immagini accanto alle parole. Circa ottocento arrivano con l'app, così hanno lo stesso aspetto su ogni macchina e funzionano senza connessione.",
  "Tatoeba": "Tatoeba",
  "Part of the real-sentence practice. Most of the course is written for Micheon, and the share coming from here falls with every pack that replaces it.": "Una parte dell'esercizio con frasi vere. Quasi tutto il corso è scritto per Micheon, e la quota che arriva da qui cala a ogni pacchetto che la sostituisce.",
  "Lucide": "Lucide",
  "The interface icons.": "Le icone dell'interfaccia.",
