  "What the desktop app is built with.": "Quello con cui è costruita l'app desktop.",
  "Also stay over fullscreen games, watch-only — clicks pass straight through. Some machines still give the game up a frame for anything drawn over it.": "Resta anche sopra i giochi a schermo intero, solo da guardare: i clic passano dritti attraverso. Su certe macchine il gioco perde comunque un fotogramma per qualsiasi cosa disegnata sopra.",
  "🌱 I'm new to coding": "🌱 Sono nuovo alla programmazione",
  "colour, practise": "colour, practise",
  "color, practice": "color, practice",
  "Walks each card up the stages you set. The one that tracks progress.": "Fa salire ogni carta lungo le fasi che imposti. È quella che segue i progressi.",
  "Flip through at your own pace. Nothing is graded.": "Sfoglia al tuo ritmo. Non viene valutato niente.",
  "Answer the whole set, then see a score and every correction.": "Rispondi a tutto il gruppo, poi guarda il punteggio e ogni correzione.",
  "Match": "Abbina",
  "Pair terms against definitions, against the clock.": "Accoppia i termini con le definizioni, contro il cronometro.",
  "Builds the set into your memory. Progress only moves here.": "Fissa il gruppo nella tua memoria. I progressi si muovono solo qui.",
  "Checks where you stand. Graded, and it changes nothing.": "Controlla a che punto sei. Viene valutato, e non cambia niente.",
  "Test": "Prova",
