  "A1–A2 · Beginner": "A1–A2 · Principiante",
  "Everyday basics: greetings, ordering, simple questions about yourself.": "Le basi di tutti i giorni: saluti, ordinare, domande semplici su di te.",
  "B1 · Getting by": "B1 · Cavarsela",
  "Handling ordinary situations alone — appointments, plans, opinions in short.": "Gestire da solo le situazioni normali: appuntamenti, programmi, opinioni in breve.",
  "B2 · Conversational": "B2 · Da conversazione",
  "Keeping up with natives on familiar topics, and arguing a point.": "Stare al passo con i madrelingua su argomenti noti, e sostenere una tesi.",
  "C1 · Advanced": "C1 · Avanzato",
  "Fluent and precise, including work, study and abstract subjects.": "Sciolto e preciso, anche su lavoro, studio e temi astratti.",
  "C2 · Near-native": "C2 · Quasi madrelingua",
  "Anything a native handles: idiom, nuance, humour, fast speech.": "Tutto quello che gestisce un madrelingua: modi di dire, sfumature, umorismo, parlato veloce.",
  "All items": "Tutti gli elementi",
  "Phrases & dialogues": "Espressioni e dialoghi",
  "Vocabulary in context": "Lessico nel contesto",
  "All usefulness levels": "Tutti i livelli di utilità",
