  "Similar sentences together": "Frasi simili insieme",
  "The course's pick": "La scelta del corso",
  "How Continue learning is put together": "Come viene composto Continua a imparare",
  "The course's pick blends how common a sentence is with how hard it is and how far you are. Easiest first takes all of one level before the next. Most common first takes what people say most, whatever the level. Similar sentences together takes the next sentence and then every sentence that starts the same way — all the “Ich möchte …”, then all the “Kannst du …”. Conversation order takes an exchange as the dialogues have it — a question, then the answer that fits it, then what comes next. Shortest first and Longest first go by length. Reviews come back whatever the order.": "La scelta del corso unisce quanto è comune una frase, quanto è difficile e a che punto sei. Più facili prima prende tutto un livello prima del successivo. Più comuni prima prende ciò che la gente dice di più, a qualunque livello. Frasi simili insieme prende la frase successiva e poi tutte quelle che iniziano allo stesso modo — tutti gli “Ich möchte …”, poi tutti i “Kannst du …”. Ordine di conversazione prende uno scambio come lo hanno i dialoghi — una domanda, poi la risposta giusta, poi ciò che segue. Più corte prima e Più lunghe prima vanno per lunghezza. I ripassi tornano con qualsiasi ordine.",
  "Order decides what comes first and still teaches everything. This decides what a sitting draws on at all, so you can work through one level and stop. Reviews are never held back.": "L'ordine decide cosa viene prima e insegna comunque tutto. Questo decide da cosa attinge una sessione, così puoi fare un livello e fermarti. I ripassi non vengono mai trattenuti.",
  "Conversation order": "Ordine di conversazione",
  "Changing this rebuilds the sitting from the start.": "Cambiare questo ricompone la sessione dall'inizio.",

