  "The nouns for what you feel — grief to glee, named the way Germans name them.": "I sostantivi di ciò che si prova: dal lutto al giubilo, chiamati come li chiamano i tedeschi.",
  "Common words the themed packs never taught, bank ranks 1737–2489.": "Parole frequenti che i pacchetti tematici non hanno mai insegnato, posizioni 1737–2489 della banca.",
  "Reviewed words no pack taught yet, 1–31 of 156.": "Parole verificate che nessun pacchetto insegna ancora, 1–31 di 156.",
  "Reviewed words no pack taught yet, 32–62 of 156.": "Parole verificate che nessun pacchetto insegna ancora, 32–62 di 156.",
