  "Type the Greek sentence...": "Scrivi la frase greca...",
  "Type the Greek you heard": "Scrivi il greco che hai sentito",
  "Arrange the Greek words below.": "Ordina le parole greche qui sotto.",
  "Choose the Greek phrase you heard.": "Scegli la frase greca che hai sentito.",
