  "Type the whole Greek sentence — from the German above.": "Scrivi tutta la frase greca — a partire dal tedesco qui sopra.",
  "Type the whole Greek sentence — from the English above.": "Scrivi tutta la frase greca — a partire dall'inglese qui sopra.",
