  "Type the whole Greek sentence — from the Portuguese above.": "Scrivi tutta la frase greca — a partire dal portoghese qui sopra.",
  "Type the whole Greek sentence — from the Russian above.": "Scrivi tutta la frase greca — a partire dal russo qui sopra.",
  "Your turn — say it in Greek": "Tocca a te: dillo in greco",
  "Greek repeats": "Ripetizioni del greco",
  "Greek voice is muted and will be skipped.": "La voce greca è silenziata e verrà saltata.",
  "Your turn to say the Greek before it is spoken": "Tocca a te dire il greco prima che venga pronunciato",
  "Greek first": "Greco prima",
  "Greek tip: every word of two or more syllables carries one accent mark, and it shows where the stress falls — καλημέρα, ευχαριστώ.": "Consiglio di greco: ogni parola di due o più sillabe porta un accento scritto, che indica dove cade l'accento tonico — καλημέρα, ευχαριστώ.",
  "Greek tip: a question ends in ; — “Τι κάνεις;” is how are you.": "Consiglio di greco: una domanda finisce con ; — “Τι κάνεις;” vuol dire come stai.",
  "Greek tip: σ becomes ς at the end of a word — ο φίλος, but οι φίλοι.": "Consiglio di greco: σ diventa ς in fondo alla parola — ο φίλος, ma οι φίλοι.",
  "Greek tip: the ending already says who — “πάω” is I go, so “εγώ πάω” puts the stress on the I.": "Consiglio di greco: la desinenza dice già chi: “πάω” vuol dire io vado, quindi “εγώ πάω” mette l'accento sull'io.",
  "Greek tip: names take the article too — ο Γιάννης, η Μαρία.": "Consiglio di greco: anche i nomi prendono l'articolo — ο Γιάννης, η Μαρία.",
